    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: What is the primary hormonal change that initiates the cascade leading to labor at term?', '["Decrease in maternal cortisol", "Increase in placental CRH and fetal cortisol", "Increase in progesterone", "Decrease in oxytocin receptors"]', 1, 'The fetal-placental clock involving CRH and fetal cortisol is the primary initiator. (Williams Obstetrics)'),
    (v_topic_id, '2: Which prostaglandin is most responsible for cervical ripening before the onset of active labor?', '["PGI2", "PGE2 (Dinoprostone)", "PGF2-alpha", "TXA2"]', 1, 'PGE2 is used clinically for ripening because it mimics the natural process of collagen breakdown. (Beckmann)'),
    (v_topic_id, '3: The "First Stage of Labor" is divided into which two phases?', '["Latent and Active", "Early and Late", "Dilation and Effacement", "Propulsion and Expulsion"]', 0, 'Stage 1 starts with regular contractions and ends with full dilation. (Williams)'),
    (v_topic_id, '4: According to modern ACOG guidelines (Zhang curve), at what cervical dilation does the "Active Phase" of labor typically begin?', '["3 cm", "4 cm", "6 cm", "8 cm"]', 2, 'Contemporary data suggests the active phase begins at 6 cm, later than previously taught. (ACOG)'),
    (v_topic_id, '5: "Cervical Effacement" refers to:', '["The opening of the internal os", "The thinning and shortening of the cervix", "The softening of the cervix", "The descent of the fetal head"]', 1, 'Expressed as a percentage from 0% to 100%. (Beckmann)'),
    (v_topic_id, '6: A "Bloody Show" occurs during early labor because of:', '["Placenta previa", "Rupture of small vessels as the cervix dilates and the mucus plug is expelled", "Abruption", "Vaginitis"]', 1, 'This is a normal sign of impending or early labor. (Williams)'),
    (v_topic_id, '7: The "Occipitobregmatic" diameter is the smallest diameter of the fetal head. Which fetal position presents this diameter to the pelvis?', '["Extension", "Flexion", "Asynclitism", "Military position"]', 1, 'Flexion allows the smallest diameter to pass through the birth canal. (Beckmann)'),
    (v_topic_id, '8: "Engagement" of the fetal head is defined as when the widest part of the head has passed through:', '["The vulva", "The ischial spines", "The pelvic inlet", "The internal os"]', 2, 'Engagement usually happens at station 0. (Williams)'),
    (v_topic_id, '9: If the sagittal suture is closer to the symphysis pubis than the sacrum, the head is in:', '["Posterior asynclitism", "Anterior asynclitism", "Synclitism", "Face presentation"]', 0, 'The posterior parietal bone is presenting more. (Beckmann)'),
    (v_topic_id, '10: A "G1P0" at 4 cm dilation has had no cervical change for 6 hours despite regular contractions. What is the next best step?', '["Immediate C-section", "Wait; she is not in the active phase yet", "Artificial Rupture of Membranes (AROM)", "Start Oxytocin"]', 1, 'Active phase arrest cannot be diagnosed before 6 cm. (ACOG)'),
    (v_topic_id, '11: Which pelvic shape is characterized by an oval inlet with a long anteroposterior diameter and is associated with persistent Occiput Posterior (OP) position?', '["Gynecoid", "Android", "Anthropoid", "Platypelloid"]', 2, 'Common in non-White populations; favors OP. (Williams)'),
    (v_topic_id, '12: What is the "Gold Standard" for measuring the strength of uterine contractions?', '["Palpation", "External Tocodynamometry", "Intrauterine Pressure Catheter (IUPC)", "Ultrasound"]', 2, 'IUPC measures actual pressure in Montevideo Units (MVUs). (Beckmann)'),
    (v_topic_id, '13: "Adequate" contractions in the active phase are generally defined as how many Montevideo Units (MVUs) over 10 minutes?', '["50-100", "150-200", "200-250", "> 400"]', 2, '200 MVUs is the traditional threshold for adequacy. (Williams)'),
    (v_topic_id, '14: A patient at 39 weeks has regular contractions. Cervix is 3 cm dilated, 50% effaced, and -2 station. She remains at 3 cm for 8 hours. Diagnosis?', '["Active phase arrest", "Protracted latent phase", "Normal latent phase", "False labor"]', 2, 'The latent phase can last up to 20 hours in nulliparas. (ACOG)'),
    (v_topic_id, '15: What is the primary risk associated with Artificial Rupture of Membranes (AROM) if the fetal head is not well-engaged?', '["Infection", "Umbilical cord prolapse", "Abruption", "Maternal hemorrhage"]', 1, 'The cord can wash down past the head with the fluid. (Beckmann)'),
    (v_topic_id, '16: "Chorioamnionitis" (Intra-amniotic infection) is a risk of prolonged rupture of membranes. Which of the following is the most sensitive clinical sign?', '["Uterine tenderness", "Maternal fever", "Fetal tachycardia", "Foul-smelling fluid"]', 2, 'Fetal tachycardia often precedes maternal fever. (Williams)'),
    (v_topic_id, '17: Management of "Active Phase Arrest" (no change > 4h with adequate MVUs or > 6h with oxytocin)?', '["Wait another 6 hours", "Cesarean delivery", "Forceps", "Vacuum"]', 1, 'Arrest in the active phase is an indication for C-section. (ACOG)'),
    (v_topic_id, '18: During the first stage of labor, fetal heart rate (FHR) should be reviewed how often in a low-risk patient?', '["Every 5 min", "Every 15 min", "Every 30 min", "Every hour"]', 2, 'Every 15 min for high risk; every 30 min for low risk. (Beckmann)'),
    (v_topic_id, '19: A "Nitrazine test" that turns blue indicates a pH of > 6.5, suggestive of:', '["Vaginal secretions", "Amniotic fluid", "Urine", "Semen"]', 1, 'Amniotic fluid is alkaline. Note that blood or semen can cause false positives. (Williams)'),
    (v_topic_id, '20: "Fern Test" confirms rupture of membranes by showing:', '["Blue crystals", "Microscopic arborization (fern-like pattern) of dried fluid", "WBCs", "Glucose"]', 1, 'Due to sodium chloride content in amniotic fluid. (Beckmann)'),
    (v_topic_id, '21: Which maneuver is used to determine fetal lie, presentation, and position via abdominal palpation?', '["McRoberts", "Leopold maneuvers", "Zavanelli", "Mauriceau-Smellie-Veit"]', 1, 'Four steps of palpation. (Williams)'),
    (v_topic_id, '22: If the fetal occiput is directed toward the maternal left and anterior, the position is:', '["ROA", "LOA", "LOT", "LOP"]', 1, 'Left Occiput Anterior. (Beckmann)'),
    (v_topic_id, '23: What is the most common fetal "Lie" at term?', '["Transverse", "Oblique", "Longitudinal", "Breech"]', 2, 'Longitudinal (Cephalic or Breech). (Williams)'),
    (v_topic_id, '24: "False Labor" (Braxton Hicks) is distinguished from true labor by:', '["Intensity", "Absence of cervical change", "Presence of mucus plug", "Location of pain"]', 1, 'True labor requires progressive cervical dilation/effacement. (Beckmann)'),
    (v_topic_id, '25: The "Pelvic Floor" is formed primarily by which muscle group?', '["Gluteus maximus", "Levator Ani", "Obturator internus", "Piriformis"]', 1, 'Pubococcygeus, puborectalis, and iliococcygeus. (Williams)'),
    (v_topic_id, '26: Which of the following is a contraindication to vaginal delivery?', '["Previous C-section (low transverse)", "Active genital Herpes simplex virus (HSV) lesions", "Gestational diabetes", "Mild pre-eclampsia"]', 1, 'High risk of neonatal transmission. (ACOG)'),
    (v_topic_id, '27: "Precipitous Labor" is defined as labor lasting less than:', '["1 hour", "3 hours", "6 hours", "12 hours"]', 1, 'Associated with increased risk of PPH and fetal trauma. (Williams)'),
    (v_topic_id, '28: What is the primary cause of "Early Decelerations" on FHR tracing?', '["Uteroplacental insufficiency", "Head compression", "Cord compression", "Fetal sleep"]', 1, 'Vagal response to compression; benign. (Beckmann)'),
    (v_topic_id, '29: "Variable Decelerations" on FHR monitoring suggest:', '["Head compression", "Umbilical cord compression", "Placental abruption", "Maternal fever"]', 1, 'Often improved with maternal position change. (ACOG)'),
    (v_topic_id, '30: "Late Decelerations" indicate:', '["Fetal well-being", "Uteroplacental insufficiency (hypoxia)", "Normal labor", "Rapid descent"]', 1, 'Concerning finding; requires resuscitation maneuvers. (Williams)'),
    (v_topic_id, '31: Fetal "Station" +3 indicates the head is:', '["At the ischial spines", "Floating", "Deep in the pelvis, near the introitus", "Above the inlet"]', 2, 'Positive stations are below the spines. (Beckmann)'),
    (v_topic_id, '32: "Molding" of the fetal head during labor is caused by:', '["Brain swelling", "The overlap of cranial bones at sutures to adapt to the pelvis", "Scalp edema", "Fracture"]', 1, 'Normal physiological process. (Williams)'),
    (v_topic_id, '33: "Caput Succedaneum" is:', '["Blood under the periosteum", "Edema of the scalp that crosses suture lines", "A skull fracture", "Intracranial bleed"]', 1, 'Differentiated from cephalohematoma (which does not cross sutures). (Beckmann)'),
    (v_topic_id, '34: What is the most common indication for "Induction of Labor"?', '["Maternal request", "Post-term pregnancy (>= 41-42 weeks)", "Twins", "Large baby"]', 1, 'Reduced risk of stillbirth in post-term. (ACOG)'),
    (v_topic_id, '35: Which Bishop score usually indicates a "ripe" cervix and high likelihood of successful induction?', '["< 3", "4-5", ">= 6-8", "Only 13"]', 2, 'Higher score = more favorable. (Williams)'),
    (v_topic_id, '36: "Oxytocin" carries which major risk if titrated too aggressively?', '["Uterine tachysystole and fetal distress", "Diabetes", "Hypertension", "Renal failure"]', 0, 'Excessive contractions can compromise blood flow to the placenta. (ACOG)'),
    (v_topic_id, '37: Maternal "Pushing" occurs during which stage of labor?', '["Stage 1", "Stage 2", "Stage 3", "Stage 4"]', 1, 'The expulsion stage. (Beckmann)'),
    (v_topic_id, '38: The "Ferguson Reflex" refers to:', '["Fetal breathing", "Release of oxytocin triggered by cervical stretching", "The urge to vomit in labor", "Sudden drop in BP"]', 1, 'Positive feedback loop for labor. (Williams)'),
    (v_topic_id, '39: Epidural anesthesia is typically placed in which space?', '["Subarachnoid", "Epidural space (outside the dura)", "Intramuscular", "Venous"]', 1, 'Allows for continuous infusion. (Beckmann)'),
    (v_topic_id, '40: A common side effect of Epidural anesthesia that can affect fetal heart rate is:', '["Maternal Hypertension", "Maternal Hypotension", "Fever", "Tachycardia"]', 1, 'Due to sympathetic blockade; treated with IV fluids and phenylephrine/ephedrine. (Williams)'),
    (v_topic_id, '41: "Spinal" anesthesia is most commonly used for:', '["Normal vaginal birth", "Cesarean section", "Early labor pain", "Induction"]', 1, 'Provides rapid, dense block. (Beckmann)'),
    (v_topic_id, '42: "Internal Rotation" typically results in the fetus being in which position?', '["Occiput Posterior (OP)", "Occiput Anterior (OA)", "Transverse", "Face presentation"]', 1, 'OA is the most common exit position. (Williams)'),
    (v_topic_id, '43: "Extension" of the head occurs as it:', '["Engages", "Passes the ischial spines", "Passes under the symphysis pubis", "Delivers the shoulders"]', 2, 'The head tilts upward to emerge. (Beckmann)'),
    (v_topic_id, '44: "Restitution" is:', '["The head rotating 45 degrees back to line up with the shoulders", "The birth of the placenta", "The uterus shrinking", "The baby crying"]', 0, 'Also called external rotation. (Williams)'),
    (v_topic_id, '45: To deliver the anterior shoulder, the provider should apply:', '["Upward traction", "Downward traction", "Strong pressure on the fundus", "Rotate the head 360 degrees"]', 1, 'Followed by upward traction for the posterior shoulder. (Beckmann)'),
    (v_topic_id, '46: "Meconium-stained" amniotic fluid is most commonly seen in:', '["Preterm labor", "Term and Post-term labor", "Placenta previa", "GDM"]', 1, 'Increased incidence with gestational age. (Williams)'),
    (v_topic_id, '47: If a fetus has a "Non-reassuring" FHR tracing, what is the first "Resuscitation" step?', '["Immediate C-section", "Lateral maternal positioning, O2, and IV fluids", "Start oxytocin", "Amniotomy"]', 1, 'Standard conservative maneuvers. (ACOG)'),
    (v_topic_id, '48: "Uterine Tachysystole" is defined as more than _____ contractions in 10 minutes.', '["3", "5", "8", "10"]', 1, 'Averaged over 30 minutes. (ACOG)'),
    (v_topic_id, '49: The "Ritgen Maneuver" is used to:', '["Stop bleeding", "Control the delivery of the head to prevent perineal tears", "Deliver the placenta", "Turn a breech baby"]', 1, 'Applying pressure to the fetal chin through the perineum. (Williams)'),
    (v_topic_id, '50: A "First-degree" perineal laceration involves:', '["The vaginal mucosa or perineal skin only", "The perineal muscles", "The anal sphincter", "The rectal mucosa"]', 0, 'Surface level; often doesn''t need repair. (Beckmann)'),
    (v_topic_id, '51: A "Fourth-degree" laceration involves:', '["Muscle only", "The anal sphincter", "The rectal mucosa (entry into the lumen)", "The cervix"]', 2, 'Highest degree of tear. (Williams)'),
    (v_topic_id, '52: "Episiotomy" is currently recommended by ACOG to be:', '["Performed on every patient", "Performed only when clinically indicated (e.g., to speed up a distressed baby)", "Never performed", "Done only in twins"]', 1, 'Restrictive use is preferred over routine use. (ACOG)'),
    (v_topic_id, '53: "Shoulder Dystocia" is a medical emergency where the anterior shoulder is trapped behind the:', '["Sacrum", "Ischial spines", "Symphysis pubis", "Cervix"]', 2, 'Requires specific maneuvers to resolve. (Williams)'),
    (v_topic_id, '54: The "Turtle Sign" is a classic sign of:', '["Breech", "Shoulder Dystocia", "Normal delivery", "Twins"]', 1, 'Fetal head retracts against the perineum. (Beckmann)'),
    (v_topic_id, '55: "McRoberts Maneuver" involves:', '["Pushing on the fundus", "Flexing the maternal thighs against the abdomen", "Rotating the baby", "C-section"]', 1, 'Increases the pelvic outlet diameter. (ACOG)'),
    (v_topic_id, '56: "Suprapubic pressure" is applied to:', '["The fundus", "Directly over the maternal symphysis to disimpact the shoulder", "The baby''s head", "The legs"]', 1, 'Used in conjunction with McRoberts. (Williams)'),
    (v_topic_id, '57: Fundal pressure is _____ in shoulder dystocia.', '["Highly recommended", "Contindicated (may worsen impaction or cause rupture)", "Only for experts", "Always effective"]', 1, 'Never apply fundal pressure; it wedges the shoulder tighter. (ACOG)'),
    (v_topic_id, '58: The "Zavanelli Maneuver" involves:', '["Rotating the shoulders", "Pushing the head back into the uterus for an emergency C-section", "Extracting the baby by the legs", "Using a vacuum"]', 1, 'A last-resort maneuver for catastrophic dystocia. (Williams)'),
    (v_topic_id, '59: "Delayed Cord Clamping" for at least 30-60 seconds in vigorous infants is recommended to increase:', '["Oxygen", "Hemoglobin levels and iron stores", "Weight", "Intelligence"]', 1, 'Benefits both term and preterm infants. (ACOG)'),
    (v_topic_id, '60: An APGAR score is taken at which intervals?', '["Birth and 1 hour", "1 and 5 minutes", "5 and 10 minutes", "Every minute for 10 minutes"]', 1, 'Standard timing; may repeat at 10 if low. (Beckmann)');
